fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Check if string is empty
    if txt.is_empty() {
        return false;
    }
    
    // Get the last character
    let last_char = txt.chars().last().unwrap();
    
    // Check if last character is an ASCII letter
    if !last_char.is_ascii_alphabetic() {
        return false;
    }
    
    // Check the length condition
    let char_count = txt.chars().count();
    
    if char_count == 1 {
        // Single character string with ASCII letter
        return true;
    }
    
    // For strings with more than one character, check if second-to-last is a space
    let chars: Vec<char> = txt.chars().collect();
    chars[char_count - 2] == ' '
}